NAMES = [{"code": "en", "name": "English"}, {"code": "es", "name": "Español"}, {"code": "fr", "name": "Français"}, {"code": "de", "name": "Deutsch"},
         {"code": "pt", "name": "Português"}, {"code": "ru", "name": "Русский"}, {"code": "ar", "name": "العربية"}]


def main():
    tables = {code: {} for code in LANGS}
    for en, vals in T.items():
        assert len(vals) == len(LANGS), en
        for code, v in zip(LANGS, vals):
            if v != en:
                tables[code][en] = v
    import os
    os.makedirs("langs", exist_ok=True)
    with open(os.path.join("langs", "tables.json"), "w", encoding="utf-8") as f:
        json.dump({"names": NAMES, "tables": tables}, f, ensure_ascii=False)
    print(len(T), "strings,", len(LANGS), "languages")


main()
